const q = $('Schedule Page').first().json.query || {};
const raw = $input.first().json || {};
const row = {};
for (const [k, v] of Object.entries(raw)) row[String(k).trim()] = v;

const appId = String(q.applicationId || "").trim();
const token = String(q.token || "").trim();
const status = String(row.status || "").trim();
const HOUR = 3600000, SLOT = 1800000;

let reason = "";
let booked = null;
const linkOk = !row.applicationId || String(row.applicationId).trim() === appId;
if (!row.applicationId || !linkOk || !token ){
  reason = "This link is not valid.";
} else if (String(row.interviewDate || "").trim()) {
  reason = "An interview is already booked for you.";
  booked = { interviewDate: String(row.interviewDate).trim(), meetingLink: String(row.meetingLink || "").trim() };
} else if (status !== "Pending Review") {
  reason = "Scheduling is not available for this application.";
}

// Candidate slots: Sun to Thu, 10:00 to 15:30 start, Cairo time, 30-minute steps, next 8 days
const now = Date.now();
const fmt = new Intl.DateTimeFormat("en-US", { timeZone: "Africa/Cairo", weekday: "short", hour: "numeric", minute: "numeric", hour12: false });
const candidates = [];
for (let t = Math.ceil((now + 2 * HOUR) / SLOT) * SLOT; t < now + 8 * 24 * HOUR; t += SLOT) {
  const parts = {};
  fmt.formatToParts(new Date(t)).forEach(p => { parts[p.type] = p.value; });
  if (!["Sun", "Mon", "Tue", "Wed", "Thu"].includes(parts.weekday)) continue;
  const mins = Number(parts.hour) * 60 + Number(parts.minute);
  if (mins < 600 || mins > 930) continue;
  candidates.push(new Date(t).toISOString());
}

return [{ json: {
  valid: reason === "",
  reason,
  booked,
  applicationId: appId,
  token,
  applicantName: String(row.applicantName || "").trim(),
  role: String(row.appliedPosition || "the position").trim(),
  candidates,
  gcalBody: {
    timeMin: new Date(now).toISOString(),
    timeMax: new Date(now + 8 * 24 * HOUR).toISOString(),
    timeZone: "UTC",
    items: [{ id: "primary" }]
  }
} }];

const p = $('Prepare Free Busy').first().json;
const esc = (s) => String(s ?? "").replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

const CSS = `
  :root{
    --ink:#12213b; --ink-soft:#1d3258; --fog:#f3f5f9; --line:#d3dae6; --steel:#56657e;
    --hl:#ffd93d; --hl-soft:#fff3b8; --ok:#075e4b; --ok-bg:#d4f0e6; --danger:#b3261e; --danger-bg:#fdecea;
    --display:'Bricolage Grotesque','Segoe UI',system-ui,sans-serif;
    --body:'Instrument Sans',system-ui,-apple-system,'Segoe UI',sans-serif;
  }
  *{box-sizing:border-box}
  body{margin:0;background:var(--fog);color:var(--ink);font-family:var(--body);font-size:16px;line-height:1.6;-webkit-font-smoothing:antialiased}
  button{font:inherit}
  a{color:var(--ink)}

  .bar{background:#fff;border-bottom:1px solid var(--line)}
  .bar__in{display:flex;align-items:center;height:64px;padding:0 40px}
  .brand{display:inline-flex;align-items:center;gap:10px;font-family:var(--display);font-weight:700;font-size:20px;letter-spacing:-.02em}
  .brand svg{width:32px;height:32px}

  main{padding:48px 40px 80px}
  .eyebrow{margin:0 0 10px;font-size:14px;font-weight:600;color:var(--steel)}
  h1{margin:0 0 10px;font-family:var(--display);font-size:44px;font-weight:700;line-height:1.08;letter-spacing:-.03em}
  .lede{margin:0 0 34px;max-width:46rem;font-size:17px;color:var(--steel)}
  .lede strong{color:var(--ink)}

  .days{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:18px}
  .card{background:#fff;border:1px solid var(--line);border-top:4px solid var(--hl);border-radius:14px;padding:26px 28px 28px}
  .card h2{margin:0 0 16px;font-family:var(--display);font-size:20px;font-weight:700;letter-spacing:-.02em}
  .slots{display:flex;flex-wrap:wrap;gap:10px}
  .slot{min-width:110px;height:46px;padding:0 18px;border:1.5px solid var(--line);border-radius:10px;background:#fff;
    font-size:15px;font-weight:600;color:var(--ink);cursor:pointer;transition:border-color .15s,background-color .15s,color .15s}
  .slot:hover:not(:disabled){border-color:var(--ink);background:var(--ink);color:#fff}
  .slot:focus-visible{outline:3px solid var(--ink);outline-offset:2px}
  .slot:disabled{opacity:.5;cursor:wait}

  .empty{padding:40px 28px;border:1px dashed #b3bdcf;border-radius:14px;text-align:center;color:var(--steel);background:#fff}
  .empty h2{margin:0 0 6px;font-family:var(--display);font-size:22px;color:var(--ink)}

  .status{max-width:640px;margin:40px auto 0;background:#fff;border:1px solid var(--line);border-radius:14px;padding:40px 36px;text-align:center}
  .status--ok{border-top:4px solid var(--ok)}
  .status--info{border-top:4px solid var(--hl)}
  .okmark{width:52px;height:52px;margin:0 auto 18px;border-radius:50%;background:var(--ok-bg);color:var(--ok);display:flex;align-items:center;justify-content:center}
  .okmark svg{width:24px;height:24px}
  .status h1{font-size:34px;margin-bottom:12px}
  .status .lede{margin:0 auto 16px;font-size:16px}
  .when{display:inline-block;margin:6px 0 22px;padding:12px 20px;background:var(--fog);border-radius:10px;font-family:var(--display);font-size:20px;font-weight:700}
  .btn{display:inline-flex;align-items:center;justify-content:center;height:50px;padding:0 26px;border-radius:10px;background:var(--ink);color:#fff;
    text-decoration:none;font-size:16px;font-weight:600;transition:background-color .15s}
  .btn:hover{background:var(--ink-soft)}
  .btn:focus-visible{outline:3px solid var(--ink);outline-offset:2px}
  .note{margin:20px 0 0;font-size:14px;color:var(--steel)}

  @media (max-width:560px){main{padding:28px 16px 56px}.bar__in{padding:0 16px}h1{font-size:34px}.card{padding:22px 20px}.days{grid-template-columns:1fr}.status{padding:30px 22px}}
  @media (prefers-reduced-motion:reduce){*{transition:none!important}}
`;

const shell = (title, body) => `<!DOCTYPE html>
<html lang="en"><head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${title} - Shortlist</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,500..800&family=Instrument+Sans:wght@400..700&display=swap" rel="stylesheet">
<style>${CSS}</style></head><body>
<header class="bar"><div class="bar__in">
  <span class="brand">
    <svg viewBox="0 0 32 32" aria-hidden="true">
      <rect width="32" height="32" rx="8" fill="#12213B"/>
      <rect x="9" y="6" width="14" height="20" rx="2" fill="#F7F8FB"/>
      <rect x="11.5" y="10" width="9" height="2" rx="1" fill="#9AA6BA"/>
      <rect x="8" y="14.5" width="16" height="4.5" rx="1" fill="#FFD93D" opacity=".92"/>
      <rect x="11.5" y="15.5" width="9" height="2" rx="1" fill="#12213B"/>
      <rect x="11.5" y="21" width="6" height="2" rx="1" fill="#9AA6BA"/>
    </svg>
    Shortlist
  </span>
</div></header>
<main>${body}</main>
</body></html>`;

const check = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg>';

if (!p.valid) {
  if (p.booked) {
    const link = /^https:\/\//.test(p.booked.meetingLink) ? p.booked.meetingLink : "";
    return [{ json: { html: shell("Interview booked",
      '<div class="status status--ok"><div class="okmark">' + check + '</div>' +
      '<h1>Your interview is booked</h1>' +
      '<div class="when">' + esc(p.booked.interviewDate) + '</div>' +
      (link ? '<p><a class="btn" href="' + esc(link) + '" target="_blank" rel="noopener">Join the meeting</a></p>' : '') +
      '<p class="note">A calendar invitation was sent to your email.</p></div>') } }];
  }
  return [{ json: { html: shell("Scheduling",
    '<div class="status status--info"><h1>Choose your interview time</h1><p class="lede" style="margin-bottom:0">' + esc(p.reason) + '</p></div>') } }];
}

const resp = $input.first().json || {};
const busy = (resp.calendars && resp.calendars.primary && resp.calendars.primary.busy) || [];
const ranges = busy.map(b => [Date.parse(b.start), Date.parse(b.end)]);
const SLOT = 1800000;
const free = p.candidates.filter(iso => {
  const s = Date.parse(iso), e = s + SLOT;
  return !ranges.some(([bs, be]) => s < be && e > bs);
});

const dayFmt = new Intl.DateTimeFormat("en-GB", { timeZone: "Africa/Cairo", weekday: "long", day: "numeric", month: "long" });
const timeFmt = new Intl.DateTimeFormat("en-GB", { timeZone: "Africa/Cairo", hour: "2-digit", minute: "2-digit", hour12: true });
const groups = new Map();
for (const iso of free) {
  const d = dayFmt.format(new Date(iso));
  if (!groups.has(d)) groups.set(d, []);
  groups.get(d).push(iso);
}
const sections = [...groups.entries()].map(([day, isos]) =>
  '<section class="card"><h2>' + esc(day) + '</h2><div class="slots">' +
  isos.map(iso => '<button class="slot" data-slot="' + esc(iso) + '">' + esc(timeFmt.format(new Date(iso))) + '</button>').join("") +
  '</div></section>').join("");

const cfg = JSON.stringify({ applicationId: p.applicationId, token: p.token }).replace(/</g, "\\u003c");
const first = esc((p.applicantName || "").split(" ")[0] || "there");

const body = '<p class="eyebrow">Interview scheduling</p>' +
  '<h1>Choose your interview time</h1>' +
  '<p class="lede">Hi ' + first + ', pick a time for your interview for the <strong>' + esc(p.role) + '</strong> position. Times are shown in Cairo time.</p>' +
  (sections
    ? '<div class="days">' + sections + '</div>'
    : '<div class="empty"><h2>No times available right now</h2>We will contact you by email.</div>') +
  '<script>' +
  'var CFG = ' + cfg + ';' +
  'var parts = location.pathname.split("/"); parts.pop(); var book = parts.join("/") + "/schedule-book";' +
  'document.addEventListener("click", async function(e){' +
  '  var slot = e.target.getAttribute("data-slot");' +
  '  if (!slot) return;' +
  '  if (!confirm("Book this time?")) return;' +
  '  var btns = document.querySelectorAll("button.slot");' +
  '  btns.forEach(function(b){ b.disabled = true; });' +
  '  try {' +
  '    var r = await fetch(book, {method: "POST", headers: {"Content-Type": "application/json"}, body: JSON.stringify({applicationId: CFG.applicationId, token: CFG.token, slot: slot})});' +
  '    var text = await r.text(); var d;' +
  '    try { d = JSON.parse(text); } catch (err) { d = {ok: false, errors: ["Server error (" + r.status + ")."]}; }' +
  '    if (d.ok) { location.reload(); }' +
  '    else { alert((d.errors || ["Could not book this time."]).join("\\n")); location.reload(); }' +
  '  } catch (err) { alert("Could not reach the server. Please try again."); btns.forEach(function(b){ b.disabled = false; }); }' +
  '});' +
  '</script>';

return [{ json: { html: shell("Choose your interview time", body) } }];

const body = $input.first().json.body || {};
const applicationId = String(body.applicationId || "").trim();
const token = String(body.token || "").trim();
const slot = String(body.slot || "").trim();
const t = Date.parse(slot);
const now = Date.now();
const errors = [];
if (!/^APP-\d{8}-[A-Z2-9]{5}$/.test(applicationId)) errors.push("Invalid application.");
if (!token) errors.push("This link is not valid.");
if (isNaN(t)) errors.push("Invalid time.");
else {
  if (t < now + 3600000) errors.push("That time is too soon. Please choose another.");
  if (t > now + 8 * 86400000) errors.push("That time is outside the booking window.");
  if (t % 1800000 !== 0) errors.push("Invalid time slot.");
}
return [{ json: { valid: errors.length === 0, errors, applicationId, token, slot, slotMs: t } }];

const b = $('Check Booking').first().json;
const raw = $input.first().json || {};
const row = {};
for (const [k, v] of Object.entries(raw)) row[String(k).trim()] = v;

const found = Boolean(row.applicationId) && String(row.applicationId).trim() === b.applicationId;
const tokenOk = found && b.token !== "";
const booked = String(row.interviewDate || "").trim() !== "";
const status = String(row.status || "").trim();

let reason = "";
if (!found || !tokenOk) reason = "This link is not valid.";
else if (booked) reason = "An interview is already booked for you.";
else if (status !== "Pending Review") reason = "Scheduling is not available for this application.";

return [{ json: {
  ok: reason === "",
  reason,
  applicationId: b.applicationId,
  slotMs: b.slotMs,
  slot: b.slot,
  name: String(row.applicantName || "").trim(),
  email: String(row.applicantEmail || "").trim(),
  role: String(row.appliedPosition || "").trim(),
  gcalBody: {
    timeMin: new Date(b.slotMs).toISOString(),
    timeMax: new Date(b.slotMs + 1800000).toISOString(),
    timeZone: "UTC",
    items: [{ id: "primary" }]
  }
} }];

const a = $('Check Applicant').first().json;
const resp = $input.first().json || {};
const busy = (resp.calendars && resp.calendars.primary && resp.calendars.primary.busy) || [];
const s = a.slotMs, e = s + 1800000;
const taken = busy.some(b => s < Date.parse(b.end) && e > Date.parse(b.start));

const label = new Intl.DateTimeFormat("en-GB", { timeZone: "Africa/Cairo", weekday: "short", day: "numeric", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit", hour12: true }).format(new Date(s));

return [{ json: {
  free: !taken,
  reason: taken ? "This time was just taken. Please choose another." : "",
  applicationId: a.applicationId,
  slotLabel: label,
  eventBody: {
    summary: "Interview: " + (a.role || "Application") + " - " + (a.name || "Candidate"),
    description: "Application reference: " + a.applicationId,
    start: { dateTime: new Date(s).toISOString(), timeZone: "Africa/Cairo" },
    end: { dateTime: new Date(e).toISOString(), timeZone: "Africa/Cairo" },
    attendees: a.email ? [{ email: a.email }] : [],
    conferenceData: { createRequest: { requestId: a.applicationId + "-" + s, conferenceSolutionKey: { type: "hangoutsMeet" } } }
  }
} }];

const ev = $input.first().json || {};
const sf = $('Check Still Free').first().json;
return [{ json: { applicationId: sf.applicationId, interviewDate: sf.slotLabel, meetingLink: ev.hangoutLink } }];
